cd /Users/adriaan/repos/tt-challenges
echo "--- confirm app_user is not superuser ---"
docker compose exec -T db psql -U brain -d secondbrain -c "SELECT rolname, rolsuper FROM pg_roles WHERE rolname='app_user';"

echo "--- seed one test doc per portco as brain (admin path, bypasses RLS intentionally) ---"
docker compose exec -T db psql -U brain -d secondbrain -c "
INSERT INTO documents (org_id, doc_type, file_extension, status)
SELECT id, 'test', 'md', 'ready' FROM orgs WHERE slug IN ('pc1-vantage','pc2-cascade');
"

echo "--- as app_user, NO context set: expect 0 rows (fail closed) ---"
PGPASSWORD=app_user docker compose exec -T -e PGPASSWORD=app_user db psql -h localhost -U app_user -d secondbrain -c "SELECT count(*) FROM documents;"

echo "--- as app_user, scoped to pc1 only: expect 1 row ---"
PC1_ID=$(docker compose exec -T db psql -U brain -d secondbrain -tA -c "SELECT id FROM orgs WHERE slug='pc1-vantage';")
docker compose exec -T -e PGPASSWORD=app_user db psql -h localhost -U app_user -d secondbrain -c "
BEGIN;
SELECT set_config('app.current_org_ids', '$PC1_ID', true);
SELECT count(*) AS visible_to_pc1 FROM documents;
ROLLBACK;
"

echo "--- as app_user, scoped to pc2 only: must NOT see pc1's row (expect 1, its own only) ---"
PC2_ID=$(docker compose exec -T db psql -U brain -d secondbrain -tA -c "SELECT id FROM orgs WHERE slug='pc2-cascade';")
docker compose exec -T -e PGPASSWORD=app_user db psql -h localhost -U app_user -d secondbrain -c "
BEGIN;
SELECT set_config('app.current_org_ids', '$PC2_ID', true);
SELECT count(*) AS visible_to_pc2 FROM documents;
ROLLBACK;
"

echo "--- as app_user, scoped to pc2 only, try to INSERT a row claiming pc1's org_id: must be rejected ---"
docker compose exec -T -e PGPASSWORD=app_user db psql -h localhost -U app_user -d secondbrain -c "
BEGIN;
SELECT set_config('app.current_org_ids', '$PC2_ID', true);
INSERT INTO documents (org_id, doc_type, file_extension, status) VALUES ('$PC1_ID', 'test', 'md', 'ready');
ROLLBACK;
"

